package ru.stepanov.simulacrum.application.usecase.transaction;
import org.springframework.stereotype.Service;import ru.stepanov.simulacrum.application.port.DomainEventPublisherPort;import ru.stepanov.simulacrum.domain.event.TransactionCreatedEvent;import ru.stepanov.simulacrum.domain.model.shared.Money;import ru.stepanov.simulacrum.domain.model.transaction.*;import ru.stepanov.simulacrum.domain.repository.TransactionHistoryRepository;
import java.time.Instant;import java.util.UUID;import java.math.BigDecimal;
@Service public class GenerateTransactionUseCase { private final TransactionHistoryRepository repo; private final DomainEventPublisherPort publisher; public GenerateTransactionUseCase(TransactionHistoryRepository repo, DomainEventPublisherPort publisher){this.repo=repo;this.publisher=publisher;} public TransactionHistory execute(String accountId,Integer mcc,String merchantName,String merchantId,BigDecimal amount,String currency,CreditDebitCode indicator,String debtorName,String creditorName){String txId="TX-"+UUID.randomUUID().toString().substring(0,8); Instant now=Instant.now(); var tx=new TransactionHistory(txId,accountId,TransactionStatusCode.AcceptedSettlementCompleted,BankTransactionCode.ObPayment,now,now,new Money(amount,currency),indicator,merchantName,merchantId,mcc,debtorName,creditorName); repo.save(tx); publisher.publish(new TransactionCreatedEvent(UUID.randomUUID(),now,txId,accountId,"token-"+accountId,amount,currency,indicator,now,now,merchantName,merchantId,mcc,debtorName,creditorName)); return tx; } }
